<?php
namespace App\Http\Controllers;
use App\Models\InventoryOrder; use App\Models\InventoryTransaction; use App\Models\Product; use App\Models\User; use App\Notifications\InventoryOrderNotification; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Notification; use Illuminate\Validation\Rule;
class InventoryOrderController extends Controller {
 public function index(Request $r,string $direction){abort_unless($r->user()->canManageStock(),403);abort_unless(in_array($direction,['purchase','sale'],true),404);$orders=InventoryOrder::where('direction',$direction)->with('user')->latest()->paginate(15);return view('orders.index',compact('orders','direction'));}
 public function latest(Request $r,string $direction){abort_unless($r->user()->canManageStock(),403);abort_unless(in_array($direction,['purchase','sale'],true),404);return response()->json(InventoryOrder::where('direction',$direction)->latest()->take(15)->get(['id','order_number','contact_name','status','approved_at','created_at'])->map(fn($o)=>['id'=>$o->id,'number'=>$o->order_number,'contact'=>$o->contact_name,'status'=>$o->status,'approved'=>(bool)$o->approved_at,'created'=>$o->created_at?->format('M j, Y'),'url'=>route('orders.show',$o)]));}
 public function create(Request $r){abort_unless($r->user()->canManageStock(),403);$direction=$r->validate(['direction'=>['required',Rule::in(['purchase','sale'])]])['direction'];$products=Product::orderBy('name')->get();return view('orders.create',compact('direction','products'));}
 public function store(Request $r){abort_unless($r->user()->canManageStock(),403);$v=$r->validate(['direction'=>['required',Rule::in(['purchase','sale'])],'contact_name'=>'required|string|max:255','notes'=>'nullable|string|max:2000','items'=>'required|array|min:1','items.*.product_id'=>'required|exists:products,id','items.*.quantity'=>'required|integer|min:1|max:1000000','items.*.unit_price'=>'nullable|numeric|min:0']);$o=DB::transaction(function()use($v,$r){$o=InventoryOrder::create(['order_number'=>'TEMP-'.uniqid(),'direction'=>$v['direction'],'contact_name'=>$v['contact_name'],'notes'=>$v['notes']??null,'user_id'=>$r->user()->id]);$o->update(['order_number'=>strtoupper($v['direction']==='purchase'?'PO':'SO').'-'.now()->format('Y').'-'.str_pad((string)$o->id,6,'0',STR_PAD_LEFT)]);foreach($v['items'] as $i){$p=Product::findOrFail($i['product_id']);$o->items()->create(['product_id'=>$p->id,'quantity'=>$i['quantity'],'unit_price'=>$i['unit_price']??$p->unit_price]);}return $o;});if($r->user()->isStaff())$this->notifyAdmins($o,'created');return redirect()->route('orders.show',$o)->with('success','Order created and awaiting admin approval.');}
 public function show(Request $r,InventoryOrder $order){abort_unless($r->user()->canManageStock(),403);$order->load(['items.product','user','approver']);$listRoute=$order->direction==='purchase'?'purchase-orders.index':'sales-orders.index';return view('orders.show',compact('order','listRoute'));}
 public function status(Request $r,InventoryOrder $order){abort_unless($r->user()->canManageStock(),403);$order->loadMissing('approver');return response()->json(['status'=>$order->status,'approved'=>(bool)$order->approved_at,'approver'=>$order->approver?->name,'approved_at'=>$order->approved_at?->format('M j, Y g:i A')]);}
 public function approve(Request $r,InventoryOrder $order){abort_unless($r->user()->isAdmin(),403);if($order->status!=='pending'||$order->approved_at)return back()->with('error','This order is not awaiting approval.');if((int)$order->user_id===(int)$r->user()->id)return back()->with('error','You cannot approve your own order.');$order->update(['approved_by'=>$r->user()->id,'approved_at'=>now()]);if($order->user)Notification::send($order->user,new InventoryOrderNotification($order,'approved'));return back()->with('success','Order approved.');}
 public function complete(Request $r,InventoryOrder $order){abort_unless($r->user()->canManageStock(),403);if($order->status!=='pending'||!$order->approved_at)return back()->with('error','An admin must approve this order before processing.');try{DB::transaction(function()use($order,$r){$order->load('items.product');foreach($order->items as $i)InventoryTransaction::create(['product_id'=>$i->product_id,'type'=>$order->direction==='purchase'?InventoryTransaction::TYPE_IN:InventoryTransaction::TYPE_OUT,'quantity'=>$i->quantity,'reference_number'=>$order->order_number,'notes'=>($order->direction==='purchase'?'Received purchase order from ':'Fulfilled sales order for ').$order->contact_name,'user_id'=>$r->user()->id]);$order->update(['status'=>'completed','completed_at'=>now()]);});}catch(\App\Exceptions\InsufficientStockException $e){return back()->with('error',$e->getMessage());}if($r->user()->isStaff())$this->notifyAdmins($order,'completed');return back()->with('success','Order processed and inventory ledger updated.');}
 public function cancel(Request $r,InventoryOrder $order){abort_unless($r->user()->isAdmin(),403);if($order->status!=='pending')return back()->with('error','Only pending orders can be cancelled.');$order->update(['status'=>'cancelled']);return back()->with('success','Order cancelled.');}
 private function notifyAdmins(InventoryOrder $order,string $event):void { try { Notification::send(User::admins()->get(),new InventoryOrderNotification($order,$event)); } catch(\Throwable $e) { report($e); } }
}
